   148  bool KArchive::open(QIODevice::OpenMode mode)
   149  {
   150      Q_ASSERT(mode != QIODevice::NotOpen);
   151
   152      if (isOpen()) {
   153          close();
   154      }
   155
   156      if (!d->fileName.isEmpty()) {
   157          Q_ASSERT(!d->dev);
   158          if (!createDevice(mode)) {
   159              return false;
   160          }
   161      }
   162
   163      if (!d->dev) {
   164          setErrorString(tr("No filename or device was specified"));
   165          return false;
   166      }
   167
   168      if (!d->dev->isOpen() && !d->dev->open(mode)) {
   169          setErrorString(tr("Could not set device mode to %1").arg(mode));
   170          return false;
   171      }
   172
   173      d->mode = mode;
   174
   175      Q_ASSERT(!d->rootDir);
   176      d->rootDir = nullptr;
   177
   178      return openArchive(mode);
   179  }
